# Staples you almost always have: they count for calories but not for "you have X of Y".
STAPLES = {"Vegetable oil", "Olive oil", "Garlic", "Butter", "Honey", "Soy sauce", "Lemon juice"}

# Words used to recognise each ingredient in your fridge (English + Spanish, accents ignored).
# Matching rule (same as the app): multi-word keys must appear as a phrase; single-word keys must equal a
# word in the item's name (plural -s/-es allowed), and only keys of 5+ letters may match the start of a word.
# EXCLUDE: if any of these words/phrases appear in the item's name, it does NOT count (e.g. "chicken broth").
